```python
from __future__ import annotations

import json
import logging
import os
from typing import Generator

import requests
from flask import Flask, Response, jsonify, request, send_from_directory, stream_with_context

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(name)s %(message)s",
)
logger = logging.getLogger(__name__)

GLM_API_URL: str = os.environ.get(
    "GLM_API_URL",
    "",
)
MAX_MESSAGES: int = 200
MAX_MESSAGE_CONTENT_LEN: int = 32_768
MAX_REQUEST_JSON_BYTES: int = 4 * 1024 * 1024
GLM_MODEL: str = os.environ.get("GLM_MODEL", "glm-4")
GLM_MAX_TOKENS: int = int(os.environ.get("GLM_MAX_TOKENS", "8192"))
GLM_TEMPERATURE: float = float(os.environ.get("GLM_TEMPERATURE", "0.7"))
GLM_TOP_P: float = float(os.environ.get("GLM_TOP_P", "0.9"))
CONNECT_TIMEOUT: float = float(os.environ.get("CONNECT_TIMEOUT", "10"))
READ_TIMEOUT: float = float(os.environ.get("READ_TIMEOUT", "120"))

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = MAX_REQUEST_JSON_BYTES

_http_session = requests.Session()
_http_session.headers.update({"User-Agent": "GLM-Proxy/1.0"})


def get_api_key() -> str:
    api_key: str = os.environ.get("GLM_API_KEY", "").strip()
    if not api_key:
        raise EnvironmentError("GLM_API_KEY environment variable is not set or is empty")
    return api_key


def _sse_error(message: str) -> str:
    return f"data: {json.dumps({'error': message}, ensure_ascii=False)}\n\n"


def _sse_data(obj: dict) -> str:
    return f"data: {json.dumps(obj, ensure_ascii=False)}\n\n"


def _sse_done() -> str:
    return "data: [DONE]\n\n"


def _validate_messages(raw: object) -> list[dict]:
    if not isinstance(raw, list):
        raise ValueError("'messages' must be a JSON array")
    if len(raw) == 0:
        raise ValueError("'messages' array must not be empty")
    if len(raw) > MAX_MESSAGES:
        raise ValueError(f"'messages' array exceeds the maximum of {MAX_MESSAGES} items")
    validated: list[dict] = []
    for idx, msg in enumerate(raw):
        if not isinstance(msg, dict):
            raise ValueError(f"messages[{idx}] must be a JSON object")
        role = msg.get("role")
        content = msg.get("content")
        if role not in ("system", "user", "assistant"):
            raise ValueError(
                f"messages[{idx}].role must be one of 'system', 'user', 'assistant', got: {role!r}"
            )
        if not isinstance(content, str):
            raise ValueError(f"messages[{idx}].content must be a string")
        if len(content) > MAX_MESSAGE_CONTENT_LEN:
            raise ValueError(
                f"messages[{idx}].content exceeds maximum length of {MAX_MESSAGE_CONTENT_LEN}"
            )
        validated.append({"role": role, "content": content})
    return validated


def _last_user_content(messages: list[dict]) -> str:
    for msg in reversed(messages):
        if msg.get("role") == "user":
            content = msg.get("content", "")
            if isinstance(content, str):
                return content
    return ""


@app.route("/")
def index() -> Response:
    return send_from_directory(".", "index.html")


@app.route("/api/chat", methods=["POST"])
def chat() -> Response:
    if not request.is_json:
        return jsonify({"error": "Content-Type must be application/json"}), 415

    body: dict | None = request.get_json(silent=True, force=False)
    if body is None:
        return jsonify({"error": "Request body is not valid JSON"}), 400

    if not isinstance(body, dict):
        return jsonify({"error": "Request body must be a JSON object"}), 400

    try:
        messages = _validate_messages(body.get("messages"))
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

    search_enabled: bool = bool(body.get("search_enabled", False))

    try:
        api_key = get_api_key()
    except EnvironmentError:
        logger.error("GLM_API_KEY is not configured")
        return jsonify({"error": "Server configuration error"}), 503

    payload: dict = {
        "model": GLM_MODEL,
        "messages": messages,
        "stream": True,
        "thinking": {
            "type": "enabled",
            "clear_thinking": True,
        },
        "max_tokens": GLM_MAX_TOKENS,
        "temperature": GLM_TEMPERATURE,
        "top_p": GLM_TOP_P,
        "do_sample": True,
    }

    if search_enabled:
        payload["tools"] = [
            {
                "type": "web_search",
                "web_search": {
                    "enable": True,
                    "search_query": _last_user_content(messages),
                },
            }
        ]

    upstream_headers: dict[str, str] = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "User-Agent": "GLM-Proxy/1.0",
    }

    def generate() -> Generator[str, None, None]:
        upstream_response: requests.Response | None = None
        try:
            upstream_response = _http_session.post(
                GLM_API_URL,
                headers=upstream_headers,
                json=payload,
                stream=True,
                timeout=(CONNECT_TIMEOUT, READ_TIMEOUT),
            )

            if upstream_response.status_code != 200:
                try:
                    error_body: dict = upstream_response.json()
                    error_node = error_body.get("error")
                    if isinstance(error_node, dict):
                        error_detail: str = error_node.get("message", "Upstream API error")
                    else:
                        error_detail = "Upstream API error"
                except Exception:
                    error_detail = "Upstream API returned a non-200 response"
                logger.error("GLM API non-200: status=%d", upstream_response.status_code)
                yield _sse_error(error_detail)
                return

            done_sent: bool = False
            for raw_line in upstream_response.iter_lines(decode_unicode=True):
                if not raw_line:
                    continue
                if not raw_line.startswith("data:"):
                    continue
                data_content: str = raw_line[5:].lstrip(" ")
                if data_content == "[DONE]":
                    yield _sse_done()
                    done_sent = True
                    break

                try:
                    chunk: dict = json.loads(data_content)
                except json.JSONDecodeError:
                    logger.debug("Skipping malformed SSE JSON line")
                    continue

                if not isinstance(chunk, dict):
                    continue

                choices = chunk.get("choices")
                if not isinstance(choices, list) or len(choices) == 0:
                    continue

                choice = choices[0]
                if not isinstance(choice, dict):
                    continue

                delta = choice.get("delta")
                if not isinstance(delta, dict):
                    continue

                response_obj: dict = {}

                content_val = delta.get("content")
                if isinstance(content_val, str) and content_val:
                    response_obj["content"] = content_val

                reasoning_val = delta.get("reasoning_content")
                if isinstance(reasoning_val, str) and reasoning_val:
                    response_obj["reasoning"] = reasoning_val

                web_search_val = chunk.get("web_search")
                if isinstance(web_search_val, (dict, list)):
                    response_obj["web_search"] = web_search_val

                if response_obj:
                    yield _sse_data(response_obj)

            if not done_sent:
                yield _sse_done()

        except requests.exceptions.ConnectTimeout:
            logger.error("Connect timeout to GLM API")
            yield _sse_error("Connection to upstream API timed out")
        except requests.exceptions.ReadTimeout:
            logger.error("Read timeout streaming GLM API response")
            yield _sse_error("Upstream API read timed out")
        except requests.exceptions.ConnectionError:
            logger.error("Connection error to GLM API")
            yield _sse_error("Failed to connect to upstream API")
        except requests.exceptions.RequestException:
            logger.error("RequestException reaching GLM API")
            yield _sse_error("Upstream request failed")
        except Exception:
            logger.exception("Unexpected error in stream generator")
            yield _sse_error("Internal server error")
        finally:
            if upstream_response is not None:
                upstream_response.close()

    sse_response = Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
    )
    sse_response.headers["Cache-Control"] = "no-cache"
    sse_response.headers["X-Accel-Buffering"] = "no"
    sse_response.headers["Connection"] = "keep-alive"
    return sse_response


@app.route("/api/health", methods=["GET"])
def health() -> Response:
    api_key_present: bool = bool(os.environ.get("GLM_API_KEY", "").strip())
    return jsonify(
        {
            "status": "ok" if api_key_present else "degraded",
            "api_configured": api_key_present,
        }
    ), 200


if __name__ == "__main__":
    host: str = os.environ.get("HOST", "0.0.0.0")
    port: int = int(os.environ.get("PORT", "5000"))
    if os.environ.get("GLM_API_KEY", "").strip():
        logger.info("GLM API key is configured")
    else:
        logger.warning("GLM_API_KEY is not set")
    app.run(host=host, port=port, debug=False)
