GLM_MODEL: str = os.environ.get("GLM_MODEL", "glm-5")
GLM_MAX_TOKENS: int = int(os.environ.get("GLM_MAX_TOKENS", "131072"))
GLM_DEFAULT_TEMPERATURE: float = float(os.environ.get("GLM_TEMPERATURE", "1.0"))
CONNECT_TIMEOUT: float = float(os.environ.get("CONNECT_TIMEOUT", "10"))
READ_TIMEOUT: float = float(os.environ.get("READ_TIMEOUT", "300"))

_VALID_ROLES: frozenset[str] = frozenset({"system", "user", "assistant", "tool"})

app = Flask(__name__)
app.config["MAX_CONTENT_LENGTH"] = MAX_REQUEST_JSON_BYTES

_http_session = requests.Session()
_http_session.headers.update({"User-Agent": "GLM-Proxy/1.0"})


def get_api_key() -> str:
    api_key: str = os.environ.get("GLM_API_KEY", "").strip()
    if not api_key:
        raise EnvironmentError("GLM_API_KEY environment variable is not set or is empty")
    return api_key


def _sse_error(message: str) -> str:
    return f"data: {json.dumps({'error': message}, ensure_ascii=False)}\n\n"


def _sse_data(obj: dict) -> str:
    return f"data: {json.dumps(obj, ensure_ascii=False)}\n\n"


def _sse_done() -> str:
    return "data: [DONE]\n\n"


def _validate_messages(raw: object) -> list[dict]:
    if not isinstance(raw, list):
        raise ValueError("'messages' must be a JSON array")
    if len(raw) == 0:
        raise ValueError("'messages' array must not be empty")
    if len(raw) > MAX_MESSAGES:
        raise ValueError(f"'messages' array exceeds the maximum of {MAX_MESSAGES} items")
    validated: list[dict] = []
    for idx, msg in enumerate(raw):
        if not isinstance(msg, dict):
            raise ValueError(f"messages[{idx}] must be a JSON object")
        role = msg.get("role")
        if role not in _VALID_ROLES:
            raise ValueError(
                f"messages[{idx}].role must be one of {sorted(_VALID_ROLES)}, got: {role!r}"
            )
        out: dict[str, Any] = {"role": role}
        if role == "tool":
            tool_call_id = msg.get("tool_call_id")
            if not isinstance(tool_call_id, str) or not tool_call_id:
                raise ValueError(
                    f"messages[{idx}].tool_call_id must be a non-empty string for role 'tool'"
                )
            content = msg.get("content")
            if not isinstance(content, str):
                raise ValueError(f"messages[{idx}].content must be a string")
            out["tool_call_id"] = tool_call_id
            out["content"] = content
        elif role == "assistant":
            content = msg.get("content")
            tool_calls = msg.get("tool_calls")
            reasoning_content = msg.get("reasoning_content")
            if content is None and tool_calls is None:
                raise ValueError(
                    f"messages[{idx}] of role 'assistant' must have 'content' or 'tool_calls'"
                )
            if content is not None:
                if not isinstance(content, str):
                    raise ValueError(f"messages[{idx}].content must be a string or null")
                if len(content) > MAX_MESSAGE_CONTENT_LEN:
                    raise ValueError(
                        f"messages[{idx}].content exceeds maximum length of {MAX_MESSAGE_CONTENT_LEN}"
                    )
                out["content"] = content
            if tool_calls is not None:
                if not isinstance(tool_calls, list):
                    raise ValueError(f"messages[{idx}].tool_calls must be a JSON array")
                for tc_idx, tc in enumerate(tool_calls):
                    if not isinstance(tc, dict):
                        raise ValueError(
                            f"messages[{idx}].tool_calls[{tc_idx}] must be a JSON object"
                        )
                    if not isinstance(tc.get("id"), str) or not tc["id"]:
                        raise ValueError(
                            f"messages[{idx}].tool_calls[{tc_idx}].id must be a non-empty string"
                        )
                    if tc.get("type") != "function":
                        raise ValueError(
                            f"messages[{idx}].tool_calls[{tc_idx}].type must be 'function'"
                        )
                    fn = tc.get("function")
                    if not isinstance(fn, dict):
                        raise ValueError(
                            f"messages[{idx}].tool_calls[{tc_idx}].function must be a JSON object"
                        )
                    if not isinstance(fn.get("name"), str) or not fn["name"]:
                        raise ValueError(
                            f"messages[{idx}].tool_calls[{tc_idx}].function.name must be a non-empty string"
                        )
                    if not isinstance(fn.get("arguments"), str):
                        raise ValueError(
                            f"messages[{idx}].tool_calls[{tc_idx}].function.arguments must be a string"
                        )
                out["tool_calls"] = tool_calls
            if reasoning_content is not None:
                if not isinstance(reasoning_content, str):
                    raise ValueError(f"messages[{idx}].reasoning_content must be a string")
                out["reasoning_content"] = reasoning_content
        else:
            content = msg.get("content")
            if not isinstance(content, str):
                raise ValueError(f"messages[{idx}].content must be a string")
            if len(content) > MAX_MESSAGE_CONTENT_LEN:
                raise ValueError(
                    f"messages[{idx}].content exceeds maximum length of {MAX_MESSAGE_CONTENT_LEN}"
                )
            out["content"] = content
        validated.append(out)
    return validated


def _validate_tools(raw: object) -> list[dict] | None:
    if raw is None:
        return None
    if not isinstance(raw, list):
        raise ValueError("'tools' must be a JSON array or null")
    if len(raw) == 0:
        return None
    validated: list[dict] = []
    for idx, tool in enumerate(raw):
        if not isinstance(tool, dict):
            raise ValueError(f"tools[{idx}] must be a JSON object")
        tool_type = tool.get("type")
        if not isinstance(tool_type, str):
            raise ValueError(f"tools[{idx}].type must be a string")
        if tool_type == "function":
            fn = tool.get("function")
            if not isinstance(fn, dict):
                raise ValueError(f"tools[{idx}].function must be a JSON object")
            if not isinstance(fn.get("name"), str) or not fn["name"]:
                raise ValueError(f"tools[{idx}].function.name must be a non-empty string")
            if not isinstance(fn.get("description"), str):
                raise ValueError(f"tools[{idx}].function.description must be a string")
            if "parameters" in fn and not isinstance(fn["parameters"], dict):
                raise ValueError(f"tools[{idx}].function.parameters must be a JSON object")
        validated.append(tool)
    return validated


def _validate_response_format(raw: object) -> dict | None:
    if raw is None:
        return None
    if not isinstance(raw, dict):
        raise ValueError("'response_format' must be a JSON object or null")
    fmt_type = raw.get("type")
    if fmt_type not in ("text", "json_object"):
        raise ValueError("'response_format.type' must be 'text' or 'json_object'")
    return {"type": fmt_type}


def _last_user_content(messages: list[dict]) -> str:
    for msg in reversed(messages):
        if msg.get("role") == "user":
            content = msg.get("content", "")
            if isinstance(content, str):
                return content
    return ""


@app.route("/")
def index() -> Response:
    return send_from_directory(".", "index.html")


@app.route("/api/chat", methods=["POST"])
def chat() -> Response:
    if not request.is_json:
        return jsonify({"error": "Content-Type must be application/json"}), 415

    body: dict | None = request.get_json(silent=True, force=False)
    if body is None:
        return jsonify({"error": "Request body is not valid JSON"}), 400
    if not isinstance(body, dict):
        return jsonify({"error": "Request body must be a JSON object"}), 400

    try:
        messages = _validate_messages(body.get("messages"))
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

    try:
        custom_tools = _validate_tools(body.get("tools"))
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

    try:
        response_format = _validate_response_format(body.get("response_format"))
    except ValueError as exc:
        return jsonify({"error": str(exc)}), 400

    search_enabled: bool = bool(body.get("search_enabled", False))
    thinking_enabled: bool = bool(body.get("thinking_enabled", True))
    clear_thinking: bool = bool(body.get("clear_thinking", True))
    do_sample: bool = bool(body.get("do_sample", True))

    temperature_override = body.get("temperature")
    top_p_override = body.get("top_p")

    if temperature_override is not None and top_p_override is not None:
        return jsonify({"error": "'temperature' and 'top_p' cannot be used together"}), 400

    if temperature_override is not None:
        if not isinstance(temperature_override, (int, float)) or not (
            0.0 <= float(temperature_override) <= 2.0
        ):
            return jsonify({"error": "'temperature' must be a float between 0.0 and 2.0"}), 400

    if top_p_override is not None:
        if not isinstance(top_p_override, (int, float)) or not (
            0.0 < float(top_p_override) <= 1.0
        ):
            return jsonify(
                {"error": "'top_p' must be a float between 0 (exclusive) and 1 (inclusive)"}
            ), 400

    try:
        api_key = get_api_key()
    except EnvironmentError:
        logger.error("GLM_API_KEY is not configured")
        return jsonify({"error": "Server configuration error"}), 503

    payload: dict = {
        "model": GLM_MODEL,
        "messages": messages,
        "stream": True,
        "thinking": {
            "type": "enabled" if thinking_enabled else "disabled",
            "clear_thinking": clear_thinking,
        },
        "max_tokens": GLM_MAX_TOKENS,
        "do_sample": do_sample,
    }

    if top_p_override is not None:
        payload["top_p"] = float(top_p_override)
    else:
        payload["temperature"] = (
            float(temperature_override)
            if temperature_override is not None
            else GLM_DEFAULT_TEMPERATURE
        )

    if response_format is not None:
        payload["response_format"] = response_format

    tools: list[dict] = []
    if custom_tools:
        tools.extend(custom_tools)
    if search_enabled:
        tools.append(
            {
                "type": "web_search",
                "web_search": {
                    "enable": True,
                    "search_query": _last_user_content(messages),
                },
            }
        )
    if tools:
        payload["tools"] = tools

    upstream_headers: dict[str, str] = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "User-Agent": "GLM-Proxy/1.0",
    }

    def generate() -> Generator[str, None, None]:
        upstream_response: requests.Response | None = None
        try:
            upstream_response = _http_session.post(
                GLM_API_URL,
                headers=upstream_headers,
                json=payload,
                stream=True,
                timeout=(CONNECT_TIMEOUT, READ_TIMEOUT),
            )

            if upstream_response.status_code != 200:
                try:
                    error_body: dict = upstream_response.json()
                    error_node = error_body.get("error")
                    if isinstance(error_node, dict):
                        error_detail: str = error_node.get("message", "Upstream API error")
                    else:
                        error_detail = "Upstream API error"
                except Exception:
                    error_detail = "Upstream API returned a non-200 response"
                logger.error("GLM API non-200: status=%d", upstream_response.status_code)
                yield _sse_error(error_detail)
                return

            done_sent: bool = False
            accumulated_tool_calls: dict[int, dict] = {}

            for raw_line in upstream_response.iter_lines(decode_unicode=True):
                if not raw_line:
                    continue
                if not raw_line.startswith("data:"):
                    continue
                data_content: str = raw_line[5:].lstrip(" ")
                if data_content == "[DONE]":
                    yield _sse_done()
                    done_sent = True
                    break

                try:
                    chunk: dict = json.loads(data_content)
                except json.JSONDecodeError:
                    logger.debug("Skipping malformed SSE JSON line")
                    continue

                if not isinstance(chunk, dict):
                    continue

                choices = chunk.get("choices")
                if not isinstance(choices, list) or len(choices) == 0:
                    continue

                choice = choices[0]
                if not isinstance(choice, dict):
                    continue

                delta = choice.get("delta")
                if not isinstance(delta, dict):
                    continue

                response_obj: dict = {}

                content_val = delta.get("content")
                if isinstance(content_val, str) and content_val:
                    response_obj["content"] = content_val

                reasoning_val = delta.get("reasoning_content")
                if isinstance(reasoning_val, str) and reasoning_val:
                    response_obj["reasoning"] = reasoning_val

                tool_calls_delta = delta.get("tool_calls")
                if isinstance(tool_calls_delta, list):
                    for tc_chunk in tool_calls_delta:
                        if not isinstance(tc_chunk, dict):
                            continue
                        tc_index: int = tc_chunk.get("index", 0)
                        if tc_index not in accumulated_tool_calls:
                            accumulated_tool_calls[tc_index] = {
                                "id": "",
                                "type": "function",
                                "function": {"name": "", "arguments": ""},
                            }
                        acc = accumulated_tool_calls[tc_index]
                        if isinstance(tc_chunk.get("id"), str) and tc_chunk["id"]:
                            acc["id"] = tc_chunk["id"]
                        if isinstance(tc_chunk.get("type"), str) and tc_chunk["type"]:
                            acc["type"] = tc_chunk["type"]
                        fn_delta = tc_chunk.get("function")
                        if isinstance(fn_delta, dict):
                            if isinstance(fn_delta.get("name"), str) and fn_delta["name"]:
                                acc["function"]["name"] = fn_delta["name"]
                            if isinstance(fn_delta.get("arguments"), str):
                                acc["function"]["arguments"] += fn_delta["arguments"]

                finish_reason = choice.get("finish_reason")
                if isinstance(finish_reason, str) and finish_reason:
                    response_obj["finish_reason"] = finish_reason
                    if finish_reason == "tool_calls" and accumulated_tool_calls:
                        response_obj["tool_calls"] = list(accumulated_tool_calls.values())

                web_search_val = chunk.get("web_search")
                if isinstance(web_search_val, (dict, list)):
                    response_obj["web_search"] = web_search_val

                usage_val = chunk.get("usage")
                if isinstance(usage_val, dict):
                    response_obj["usage"] = usage_val

                if response_obj:
                    yield _sse_data(response_obj)

            if not done_sent:
                yield _sse_done()

        except requests.exceptions.ConnectTimeout:
            logger.error("Connect timeout to GLM API")
            yield _sse_error("Connection to upstream API timed out")
        except requests.exceptions.ReadTimeout:
            logger.error("Read timeout streaming GLM API response")
            yield _sse_error("Upstream API read timed out")
        except requests.exceptions.ConnectionError:
            logger.error("Connection error to GLM API")
            yield _sse_error("Failed to connect to upstream API")
        except requests.exceptions.RequestException:
            logger.error("RequestException reaching GLM API")
            yield _sse_error("Upstream request failed")
        except Exception:
            logger.exception("Unexpected error in stream generator")
            yield _sse_error("Internal server error")
        finally:
            if upstream_response is not None:
                upstream_response.close()

    sse_response = Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
    )
    sse_response.headers["Cache-Control"] = "no-cache"
    sse_response.headers["X-Accel-Buffering"] = "no"
    sse_response.headers["Connection"] = "keep-alive"
    return sse_response


@app.route("/api/health", methods=["GET"])
def health() -> Response:
    api_key_present: bool = bool(os.environ.get("GLM_API_KEY", "").strip())
    return jsonify(
        {
            "status": "ok" if api_key_present else "degraded",
            "api_configured": api_key_present,
        }
    ), 200


